"""Generates one systemd socket unit per configured client, plus the core's socket list.

Usage: python -m tg_mcp.units OUTPUT_DIR
Prints "unit user group" per socket, so the installer can check that the owners exist.
"""

import sys
from pathlib import Path

from .config import Config, load_config

SOCKET_TEMPLATE = """\
# Generated from /etc/tg-mcp/config.toml by tg_mcp.units. Do not edit.
[Unit]
Description=Telegram core socket for client "{name}"
PartOf=tg-core.service

[Socket]
ListenStream=/run/tg-core/{name}/core.sock
FileDescriptorName={name}
Service=tg-core.service
SocketUser={user}
SocketGroup={group}
SocketMode={mode}
DirectoryMode=0755
RemoveOnStop=yes

[Install]
WantedBy=sockets.target
"""


def socket_unit_name(client: str) -> str:
    return f"tg-core-{client}.socket"


def render(config: Config) -> dict[str, str]:
    """Return file contents keyed by path relative to the systemd unit directory."""
    if not config.clients:
        raise ValueError("Configure at least one [clients.NAME] section")
    files = {}
    for policy in config.clients.values():
        files[socket_unit_name(policy.name)] = SOCKET_TEMPLATE.format(
            name=policy.name, user=policy.socket_user, group=policy.socket_group, mode=policy.socket_mode
        )
    sockets = " ".join(socket_unit_name(name) for name in config.clients)
    files["tg-core.service.d/sockets.conf"] = (
        "# Generated by tg_mcp.units. Do not edit.\n"
        f"[Unit]\nRequires={sockets}\nAfter={sockets}\n\n[Service]\nSockets={sockets}\n"
    )
    return files


def main() -> None:
    output = Path(sys.argv[1])
    config = load_config()
    for relative, content in render(config).items():
        path = output / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content)
    for policy in config.clients.values():
        print(socket_unit_name(policy.name), policy.socket_user, policy.socket_group)


if __name__ == "__main__":
    main()
